// 1. Odczyt wierszy z Google Sheets
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);

// 2. Odczyt pytania użytkownika z Chat Trigger
const chatNode = $('Chat Trigger').first().json;
const chatInput = String(chatNode.chatInput || chatNode.message || chatNode.text || '').trim();

// 3. Formatowanie danych arkusza w czytelnej strukturze JSON
const sheetData = JSON.stringify(rows, null, 2);

// 4. Instrukcja systemowa z zachowaniem Strict Grounding (brak halucynacji poza arkuszem)
const systemPrompt = `Jesteś precyzyjnym asystentem danych, który odpowiada na pytania użytkownika WYŁĄCZNIE na podstawie dostarczonych danych z Arkusza Google.

ŚCISŁE ZASADY:
1. Twoja wiedza i odpowiedzi ograniczają się WYŁĄCZNIE do danych zawartych w poniższej tabeli.
2. Jeśli w arkuszu nie ma informacji potrzebnych do odpowiedzi na pytanie (np. użytkownik pyta o produkty, których nie ma w tabeli, pogodę, ogólną wiedzę o świecie, newsy itp.), odpowiedz wprost: "W arkuszu nie ma informacji na ten temat." Nie zgaduj, nie wymyślaj i nie dodawaj żadnych faktów spoza tabeli.
3. Odpowiadaj w tym samym języku, w którym zadano pytanie (np. po polsku).
4. Formułuj odpowiedzi zwięźle, konkretnie i czytelnie (używaj punktorów, pogrubień i estetycznego formatowania Markdown).
5. Jeżeli w tabeli są kolumny takie jak ilość i minimum/status, a użytkownik pyta o braki, zakupy lub stany minimalne - dokładnie przeanalizuj te wartości.`;

const userPrompt = `DANE Z ARKUSZA GOOGLE:
${sheetData}

PYTANIE UŻYTKOWNIKA:
${chatInput || '(brak pytania - przedstaw się i napisz w czym możesz pomóc na podstawie tego arkusza)'}`;

const fullPrompt = `${systemPrompt}

========================================
${userPrompt}`;

return [{
  json: {
    chatInput,
    rowCount: rows.length,
    payload: {
      contents: [
        {
          parts: [
            { text: fullPrompt }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 1500
      }
    }
  }
}];

// Wyciągnięcie odpowiedzi wygenerowanej przez Gemini i przekazanie do czatu
const resp = $input.first().json;
let reply = '';

try {
  reply = resp.candidates[0].content.parts[0].text;
} catch (e) {
  if (resp.error) {
    reply = `⚠️ Błąd API Gemini: ${resp.error.message || JSON.stringify(resp.error)}`;
  } else {
    reply = '⚠️ Przepraszam, nie udało się uzyskać odpowiedzi na podstawie danych z arkusza.';
  }
}

return [{ json: { output: reply.trim() } }];
